//! "Print backup card": opens one of the bundled, blank backup-card PDFs in the system viewer
//! (Preview), from where the user prints it. The cards are generated by
//! tools/backup-card/make_card.py and bundled as app resources (tauri.conf.json). They are the same
//! file for everyone and carry no wallet data; the user fills them in by hand from the phone. No
//! recovery word, SeedQR or other secret is ever sent to, rendered on or stored by this Mac.

use tauri::{path::BaseDirectory, AppHandle, Manager};
use tauri_plugin_opener::OpenerExt;

/// The bundled file for a paper size ("a4" | "letter") and SeedQR grid ("compact" = 25×25
/// CompactSeedQR, the phone's default; "standard" = 29×29 Standard SeedQR).
pub fn card_file(paper: &str, grid: &str) -> Result<&'static str, String> {
    Ok(match (paper, grid) {
        ("a4", "compact") => "phone-vault-backup-card-a4-compact25.pdf",
        ("a4", "standard") => "phone-vault-backup-card-a4-standard29.pdf",
        ("letter", "compact") => "phone-vault-backup-card-letter-compact25.pdf",
        ("letter", "standard") => "phone-vault-backup-card-letter-standard29.pdf",
        _ => return Err("Unknown backup card size".into()),
    })
}

#[tauri::command]
pub fn open_backup_card(app: AppHandle, paper: String, grid: String) -> Result<(), String> {
    let name = card_file(&paper, &grid)?;
    let path = app.path().resolve(format!("backup-card/{name}"), BaseDirectory::Resource).map_err(|e| e.to_string())?;
    if !path.is_file() {
        return Err("The backup card is missing from this installation.".into());
    }
    app.opener()
        .open_path(path.to_string_lossy(), None::<&str>)
        .map_err(|e| format!("Could not open the backup card: {e}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_offered_card_is_bundled_and_a_pdf() {
        let conf: serde_json::Value = serde_json::from_str(include_str!("../tauri.conf.json")).unwrap();
        let resources = conf["bundle"]["resources"].as_object().unwrap();
        for paper in ["a4", "letter"] {
            for grid in ["compact", "standard"] {
                let name = card_file(paper, grid).unwrap();
                let src = format!("../../tools/backup-card/out/{name}");
                assert_eq!(resources[&src], format!("backup-card/{name}"), "{name} not bundled");
                let bytes = std::fs::read(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(&src)).unwrap();
                assert!(bytes.starts_with(b"%PDF-1.4"), "{name} is not a PDF");
            }
        }
        assert!(card_file("a5", "compact").is_err());
        assert!(card_file("a4", "../x").is_err());
    }
}
